import{_ as e,o as t,c as s,a2 as n}from"./chunks/framework.UI9KxY5t.js";const u=JSON.parse('{"title":"一间自己的书房：年度阅读札记","description":"一年读完的书不多，但有几本改变了我看代码和生活的方式。","frontmatter":{"title":"一间自己的书房：年度阅读札记","description":"一年读完的书不多，但有几本改变了我看代码和生活的方式。","date":"2026-09-02T00:00:00.000Z","category":"浮生清欢","subCategory":"读书与摄影","tags":["阅读","年度总结","生活"],"author":"闲生"},"headers":[],"relativePath":"posts/life/reading/reading-2025.md","filePath":"posts/life/reading/reading-2025.md"}'),i={name:"posts/life/reading/reading-2025.md"};function r(l,a,o,p,d,h){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="一间自己的书房-年度阅读札记" tabindex="-1">一间自己的书房：年度阅读札记 <a class="header-anchor" href="#一间自己的书房-年度阅读札记" aria-label="Permalink to &quot;一间自己的书房：年度阅读札记&quot;">​</a></h1><p>书读得慢，反而记得住。这一年真正留下痕迹的，只有薄薄几本。</p><h2 id="一、技术之外的书" tabindex="-1">一、技术之外的书 <a class="header-anchor" href="#一、技术之外的书" aria-label="Permalink to &quot;一、技术之外的书&quot;">​</a></h2><h3 id="《瓦尔登湖》" tabindex="-1">《瓦尔登湖》 <a class="header-anchor" href="#《瓦尔登湖》" aria-label="Permalink to &quot;《瓦尔登湖》&quot;">​</a></h3><p>梭罗写湖，其实写的是「一个人需要多少东西才能生活」。读完之后，我删掉了一半的订阅源。</p><h3 id="《中国美术史》" tabindex="-1">《中国美术史》 <a class="header-anchor" href="#《中国美术史》" aria-label="Permalink to &quot;《中国美术史》&quot;">​</a></h3><p>看山水的皴法，再看自己写的界面，会突然明白留白不是空，是呼吸的地方。</p><h2 id="二、重读的技术书" tabindex="-1">二、重读的技术书 <a class="header-anchor" href="#二、重读的技术书" aria-label="Permalink to &quot;二、重读的技术书&quot;">​</a></h2><p>有些书第一遍看不懂，第二遍才读出味道。</p><ul><li>《深入理解计算机系统》：每年翻一次，每次都有新收获；</li><li>《设计数据密集型应用》：把分布式系统讲成了故事；</li><li>《代码整洁之道》：观点未必全同意，但值得对照。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>阅读计划（很松）：</span></span>
<span class="line"><span>  每天 30 分钟，不设页数；</span></span>
<span class="line"><span>  技术书与闲书交替；</span></span>
<span class="line"><span>  读完写 300 字，不求完整。</span></span></code></pre></div><h2 id="三、书房与屏幕" tabindex="-1">三、书房与屏幕 <a class="header-anchor" href="#三、书房与屏幕" aria-label="Permalink to &quot;三、书房与屏幕&quot;">​</a></h2><p>我的书桌左边是书，右边是显示器。写代码卡住的时候，随手抽一本翻两页，往往比继续盯着屏幕有效。</p><h3 id="关于摄影" tabindex="-1">关于摄影 <a class="header-anchor" href="#关于摄影" aria-label="Permalink to &quot;关于摄影&quot;">​</a></h3><p>今年拍得最多的是雨后的瓦和傍晚的窗。照片不发布，只存进一个按月份命名的文件夹。</p><p>留一间自己的书房，不为了藏书，只为了有一个地方，可以慢下来。</p>`,16)])])}const _=e(i,[["render",r]]);export{u as __pageData,_ as default};
